#include <stdio.h>

int main(void)
{
    int c = 0;
    do {
        printf("*");
        c++;
    } while (c < 2);
    puts("");
    return 0;
}

#include <stdio.h>

int main(void)
{
    int n = 0, digits = 0;
    do {
        digits++;
        n /= 10;
    } while (n > 0);
    printf("%d\n", digits);
    return 0;
}

